<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/auth.php'; require_once __DIR__.'/layout.php'; require_once dirname(__DIR__).'/services/student_portal.php';
$current=tuman_require_role('STUDENT'); $teacher=tuman_student_teacher_profile(tuman_database(),$current['id'],$_GET['id']??null); $teachers=tuman_student_teacher_assignments(tuman_database(),$current['id']); tuman_student_page_start('My Teachers');
?>
<h1>My Teachers</h1><?php if($teacher): $name=trim(($teacher['first_name']??$teacher['username']).' '.($teacher['last_name']??'')); $address=implode(', ',array_filter([$teacher['address_line1'],$teacher['address_line2'],$teacher['city'],$teacher['state_name'],$teacher['postal_code']])); ?><div class="profile-heading"><div><h2><?= htmlspecialchars($name,ENT_QUOTES,'UTF-8') ?></h2><p><strong>Email:</strong> <?= htmlspecialchars($teacher['email']??'—',ENT_QUOTES,'UTF-8') ?></p><p><strong>Telephone:</strong> <?= htmlspecialchars($teacher['phone']??'—',ENT_QUOTES,'UTF-8') ?></p><p><strong>Address:</strong> <?= htmlspecialchars($address?:'—',ENT_QUOTES,'UTF-8') ?></p></div><?php if(!empty($teacher['photo_path'])): ?><img class="profile-photo" src="<?= htmlspecialchars($teacher['photo_path'],ENT_QUOTES,'UTF-8') ?>" alt="Profile photo of <?= htmlspecialchars($name,ENT_QUOTES,'UTF-8') ?>"><?php endif; ?></div><h2>Profile details</h2><p><?= !empty($teacher['profile_details'])?nl2br(htmlspecialchars($teacher['profile_details'],ENT_QUOTES,'UTF-8')):'Not provided.' ?></p><p><a class="button" href="/Tuman/student/teachers.php">Back to my Teachers</a></p><?php else: ?><p>View the contact profile of each Teacher you are enrolled with.</p><?php if($teachers===[]): ?><p>You are not currently enrolled with a Teacher.</p><?php else: ?><table><thead><tr><th>Teacher</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($teachers as $row): ?><tr><td><?= htmlspecialchars(trim($row['first_name'].' '.($row['last_name']??'')),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($row['assignment_status']??'Active',ENT_QUOTES,'UTF-8') ?></td><td><a href="/Tuman/student/teachers.php?id=<?= (int)$row['assignment_id'] ?>">View profile</a></td></tr><?php endforeach; ?></tbody></table><?php endif; ?><?php endif; ?>
<?php tuman_student_page_end(); ?>
